// recordPlanRef は採択の束ね先 (どの回のどの問題で直すか) の構造化参照。採択した問題と一緒に
// 直した下限未満の指摘にも書く (record-schema.md の plan_ref の行)。
// 回をまたいで同因の指摘を束ねたとき (並列レビューの運用)、対応関係を
// 自由記述でなく機械で辿れる形で残す。run は同じファイル内の 1 始まりの回番号。
type recordPlanRef struct {
	Run     int    `yaml:"run"`
	Problem string `yaml:"problem"`
}

type recordPlan struct {
	ProblemID  string `yaml:"problem_id"`
	Cause      string `yaml:"cause"`
	FindingIDs []int  `yaml:"finding_ids"`
	// Approach (修正方法) と Order (順序) は review-triage-fix の立案フェーズが書く。
	// 書く条件は status ごとに決まる。pending / done / done-external では approach が
	// 必須、awaiting-human では任意 (人間の回答の後に書く)、not-fixed でも任意 (直さないと
	// 決めた問題)、investigated (調査フェーズの結果だけを持つ) では両方とも書かない。検査は recordSemanticProblems。
	Approach string `yaml:"approach"`
	// Investigation は修正方法を決める前の調査 (類似箇所・影響範囲) の範囲と結果。
	// 無いことは「未調査」を意味し、「調査済みで波及なし」は scope だけを書いた
	// 値で表す。この 2 つを記録上で区別するため、ポインタで有無を持つ。
	// status: investigated (調査済み) では必須で、無ければ検査が報告する。
	// 調査の手順の SSOT は review-triage-fix の references/investigation.md。
	Investigation *recordInvestigation `yaml:"investigation"`
	// Verification は修正の後の検証のうち、観点 B (周りの記述を再確認する) で読んだ範囲。任意だが、
	// 書くなら near_edges が要る (無いと「書いたつもりの検証」が無い扱いになる)。
	// 範囲は同梱の道具 nearedges の出力から写す (record-schema.md「検証」)。
	Verification *recordVerification `yaml:"verification"`
	// DocDag は修正の後の doc-dag の確認 (対象と、どちらが SSOT か決まっていない重複・参照の循環の有無と対処)。任意だが、
	// 書くなら scope と result が要る (record-schema.md「doc-dag の確認」)。
	DocDag *recordDocDag `yaml:"doc_dag"`
	// Decision は立案の結果 (指摘された箇所と基準、選んだ選択肢と理由)。型と検査は fix_decision.go。
	Decision  *recordDecision `yaml:"decision"`
	Options   string          `yaml:"options"`
	Order     int             `yaml:"order"`
	DependsOn []string        `yaml:"depends_on"`
	SHA       string          `yaml:"sha"`
	Status    string          `yaml:"status"`
	// AppliedExternalURL / Notes は status: done-external の反映先の記録。
	// リポジトリ外の成果物 (PR 本文・Issue のコメント・外部 Wiki など) への修正は
	// コミットが立たないので sha を書けない。URL を必須にすると、URL を持たない
	// 対象 (ローカルの外部ツール設定など) で同じ行き詰まりが起きるため、
	// 「URL か notes のどちらか」を必須にする。
	//
	// URL は sha ほど強い証拠にならない。sha はリポジトリがある限り不変だが、
	// PR 本文の URL は現在の本文を返すので、後から修正の前後を判別できないため。
	// applied_external_url は「反映先を指すもの」であって「反映内容を固定するもの」
	// ではない。だから notes には反映を確認した方法を書く。
	AppliedExternalURL string `yaml:"applied_external_url"`
	Notes              string `yaml:"notes"`
}

// recordDocDag は plans[].doc_dag (修正の後の doc-dag の確認の対象と結果)。
type recordDocDag struct {
	Scope  string `yaml:"scope"`
	Result string `yaml:"result"`
}

// recordVerification は plans[].verification を表し、観点 B で再確認した範囲 (near_edges) を持つ。
type recordVerification struct {
	NearEdges []string `yaml:"near_edges"`
}

// recordInvestigation は plans[].investigation (直す前の調査の範囲と結果)。
// scope は調べた範囲 (実行したコマンドと目で読んだ対象)、included は同じ原因の
// 別の現れとして問題に含めた箇所、excluded は見つけたが含めなかった箇所と理由。
// included / excluded が両方空なら「調べたが波及先は無かった」。
type recordInvestigation struct {
	Scope    string   `yaml:"scope"`
	Included []string `yaml:"included"`
	Excluded []string `yaml:"excluded"`
}

// recordAllowedKeys は階層ごとに許すキー。未知のキーは報告する。旧いキー名の
// 残存が「エラーなしで空」として扱われる種類の欠陥を避けるため。attrs だけは任意のキーを許す
// (上流固有の属性のパススルー)。
var recordAllowedKeys = map[string]map[string]bool{
	"トップレベル": {"runs": true},
	"実行": {"date": true, "skill": true, "run_id": true, "model": true, "level": true,
		"scope": true, "head": true, "min_fix_necessity": true, "findings": true, "plans": true, "recurrence": true, "notes": true},
	"指摘": {"id": true, "file": true, "line": true, "summary": true, "suggested_fix": true, "category": true,
		"audience": true, "audience_initial": true, "consequence": true, "premise_check": true,
		"gates_fired": true, "verdict": true, "verdict_reason": true, "plan_ref": true, "origin": true, "prior_defect": true,
		"fix_necessity": true, "fix_necessity_reason": true, "below_minimum_ref": true, "attrs": true},
	"束ね先":     {"run": true, "problem": true},
	"前からある欠陥": {"base": true, "line_check": true, "line_reason": true, "same_defect": true, "same_defect_reason": true},
	"必要度の理由":  {"goal_without_action": true, "workaround": true, "workaround_reason": true},
	"下限未満の参照": {"run": true, "finding": true, "line_check": true, "line_reason": true},
	"帰結":      {"condition": true, "who": true, "what": true, "detectability": true},
	"根拠の検証":   {"stages": true, "result": true},
	"修正計画": {"problem_id": true, "cause": true, "finding_ids": true, "approach": true,
		"investigation": true, "verification": true, "doc_dag": true, "decision": true, "options": true, "order": true, "depends_on": true, "sha": true,
		"status": true, "applied_external_url": true, "notes": true},
	"立案の結果": {"target": true, "baseline": true, "baseline_fixed": true, "choice": true, "choice_reason": true,
		"doc_change": true, "doc_change_reason": true},
	"調査":          {"scope": true, "included": true, "excluded": true},
	"検証":          {"near_edges": true},
	"doc-dag の確認": {"scope": true, "result": true},
	"検知":          {"status": true, "evidence": true, "declined_reason": true, "reframe": true},
	"根拠":          {"condition": true, "finding_id": true, "prior_run": true, "prior": true, "reason": true},
	"捉え直し":        {"pattern": true, "axes": true, "root_cause": true, "fix_unit": true, "source": true},
}

// reviewTriageRecordProblems は記録のディレクトリの YAML を検査する。
// README.md は対象外。検査は (1) スキーマ (未知キー・必須キー・列挙値・参照の整合)、
// (2) サマリの鮮度 (YAML から生成した内容と *.md の一致)、(3) 孤児のサマリ。
func reviewTriageRecordProblems(files []string, readFile func(string) ([]byte, error)) []string {
	var problems []string
var recordDateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)

// recordAudiences は被害者の列挙 (glossary のロール + 開発者)。設定 (.claude/review-triage.yaml)
// の audience と同じ値域。
var recordAudiences = map[string]bool{
	"operator": true, "admin": true, "provider": true, "developer": true,
}

// recordSemanticProblems は必須キー・列挙値・参照の整合を検査する。
func recordSemanticProblems(f string, doc *recordDoc) []string {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, f+": "+fmt.Sprintf(format, args...))
	}
	if len(doc.Runs) == 0 {
		add("runs がありません (実行が 1 つも無い)")
	}
	// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
	plansByRun := make([]map[string]bool, len(doc.Runs))
	for ri, run := range doc.Runs {
		plansByRun[ri] = map[string]bool{}
		for _, pl := range run.Plans {
			plansByRun[ri][pl.ProblemID] = true
		}
	}
	priorDefectFirstRun := recordPriorDefectFirstRun(doc.Runs)
	fixNecessityFirstRun := recordFixNecessityFirstRun(doc.Runs)
	for ri, run := range doc.Runs {
		rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
		if !recordDateRe.MatchString(run.Date) {
			add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
		}
		if run.Skill == "" {
			add("%s: skill がありません", rn)
		}
		if run.Model == "" {
			add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
		}
		if run.Scope != "incremental" && run.Scope != "full" {
			add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
		}
		if run.Head == "" {
			add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
		}
		if run.MinFixNecessity != "" && fixNecessityRank(run.MinFixNecessity) == 0 {
			add("%s: min_fix_necessity は must / should / could のいずれか (下限が無い回では書かない): %q", rn, run.MinFixNecessity)
		}

		priorDefectRequired := priorDefectFirstRun >= 0 && ri >= priorDefectFirstRun
		fixNecessityRequired := fixNecessityFirstRun >= 0 && ri >= fixNecessityFirstRun
		verdictByID := map[int]string{}
		for fi, fd := range run.Findings {
			fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
			if fd.ID <= 0 {
				add("%s: id は正の整数にする", fn)
			} else if _, dup := verdictByID[fd.ID]; dup {
				add("%s: id が同じ回の中で重複しています", fn)
			}
			verdictByID[fd.ID] = fd.Verdict
			for _, kv := range []struct{ key, val string }{
				{"file", fd.File}, {"summary", fd.Summary},
			} {
				if kv.val == "" {
					add("%s: %s がありません", fn, kv.key)
				}
			}
			switch fd.Verdict {
			case "adopted", "held", "rejected", "below_minimum":
			default:
				add("%s: verdict は adopted / held / rejected / below_minimum のいずれか: %q", fn, fd.Verdict)
			}
			if fd.VerdictReason == "" {
				add("%s: verdict_reason がありません (判定の経路をノード ID で書く)", fn)
			}
			// 指摘の出所。省略時は上流のレビュー (review)。residual はループ中に自己採択したもの
			// (record-schema.md「ループ中に記録の外で直さない」)。prior_below_minimum は、前の回までの
			// 下限未満の指摘を、この回の指摘として足したもの (同「下限未満の指摘の参照」)。
			switch fd.Origin {
			case "", "review", "residual", "prior_below_minimum":
			default:
				add("%s: origin は review / residual / prior_below_minimum のいずれか (省略時は review): %q", fn, fd.Origin)
			}
			if fd.PlanRef != nil {
				if fd.PlanRef.Run < 1 || fd.PlanRef.Run > len(doc.Runs) {
					add("%s: plan_ref の run %d は存在しません (回は 1〜%d)", fn, fd.PlanRef.Run, len(doc.Runs))
				} else if !plansByRun[fd.PlanRef.Run-1][fd.PlanRef.Problem] {
					add("%s: plan_ref の問題 %q は %d 回目の plans にありません", fn, fd.PlanRef.Problem, fd.PlanRef.Run)
				}
			}
			for _, m := range recordBelowMinimumRefProblems(doc, ri, fd) {
				add("%s: %s", fn, m)
			}
			// D9 で当たって判定を省略した指摘 (A3・B2) は、分類・被害者・帰結・根拠の検証・
			// ゲート・必要度を書かない。書かないことは recordBelowMinimumRefProblems が検査する。
			if judgmentOmitted(fd) {
				continue
			}
			for _, kv := range []struct{ key, val string }{
				{"category", fd.Category}, {"audience", fd.Audience},
			} {
				if kv.val == "" {
					add("%s: %s がありません", fn, kv.key)
				}
			}
			// audience の列挙。列挙外の値をエラーにせずに通すと D7 (被害者の判定) の入力が壊れる。
			if fd.Audience != "" && !recordAudiences[fd.Audience] {
				add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
			}
			if fd.AudienceInitial != "" && !recordAudiences[fd.AudienceInitial] {
				add("%s: audience_initial は operator / admin / provider / developer のいずれか: %q", fn, fd.AudienceInitial)
			}
			for _, kv := range []struct{ key, val string }{
				{"condition", fd.Consequence.Condition}, {"who", fd.Consequence.Who},
				{"what", fd.Consequence.What}, {"detectability", fd.Consequence.Detectability},
			} {
				if kv.val == "" {
					add("%s: consequence.%s がありません (帰結の 4 項目は必須)", fn, kv.key)
				}
			}
			switch fd.PremiseCheck.Stages {
			case "none", "A", "A+B":
			default:
				add("%s: premise_check.stages は none / A / A+B のいずれか: %q", fn, fd.PremiseCheck.Stages)
			}
			switch fd.PremiseCheck.Result {
			case "verified", "wrong", "unverifiable", "skipped":
			default:
				add("%s: premise_check.result は verified / wrong / unverifiable / skipped のいずれか: %q",
					fn, fd.PremiseCheck.Result)
			}
			if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
				add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
					fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
			}
			for _, m := range recordPriorDefectProblems(priorDefectRequired, fd) {
				add("%s: %s", fn, m)
			}
			for _, m := range recordFixNecessityProblems(fixNecessityRequired, run.MinFixNecessity, fd) {
				add("%s: %s", fn, m)
			}
		}

		// 足すはずの下限未満の指摘は、最後の回についてだけ検査する。前の回の findings は後から
		// 書き換えない (record-schema.md の「スキーマ」) ので、報告しても直せない。足し忘れは、
		// その回を書いた直後の検査 (その回が最後の回のとき) で報告される。最後の回でなくなった回の
		// 足し忘れは、後の回の検査では報告されない (その回を書いた直後に検査しなかったか、検査の失敗を
		// 直さずに次の回を書いた場合)。
		if ri == len(doc.Runs)-1 {
			for _, m := range recordPriorBelowMinimumProblems(doc, ri) {
				add("%s: %s", rn, m)
			}
		}

		problemIDs := map[string]bool{}
		for _, pl := range run.Plans {
			if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
				add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
			}
			problemIDs[pl.ProblemID] = true
		}
		for pi, pl := range run.Plans {
			pn := fmt.Sprintf("%s: plans[%d] (%s)", rn, pi, pl.ProblemID)
			for _, kv := range []struct{ key, val string }{
				{"problem_id", pl.ProblemID}, {"cause", pl.Cause},
			} {
				if kv.val == "" {
					add("%s: %s がありません", pn, kv.key)
				}
			}
			if len(pl.FindingIDs) == 0 {
				add("%s: finding_ids がありません (1 つ以上)", pn)
			}
			for _, id := range pl.FindingIDs {
				v, ok := verdictByID[id]
				if !ok {
					add("%s: finding_ids の %d は同じ回の findings にありません", pn, id)
				} else if v != "adopted" {
					add("%s: finding_ids の %d は採択 (adopted) ではありません (verdict %s)。修正計画は採択だけを束ねる", pn, id, v)
				}
			}
			// externalOnly は done-external 専用のキーが空であることを検査する。
			// スキーマ表が「done-external のときだけ書く」と定める排他で、書かせる
			// だけで検査しないと、done でコミット済みなのに外部 URL が残る記録が
			// エラーにならずに通る (sha の排他は前から検査されていた)。列挙外の status では
			// 呼ばない。default が列挙違反を報告するので、そこへ重ねると 1 つの
			// 誤字が 2 つの問題になるため。
			externalOnly := func() {
				for _, kv := range []struct{ key, val string }{
					{"applied_external_url", pl.AppliedExternalURL}, {"notes", pl.Notes},
				} {
					if kv.val != "" {
						add("%s: status %s なのに %s %q があります。%s は status done-external 専用",
							pn, pl.Status, kv.key, kv.val, kv.key)
					}
				}
			}
			// approachRequired は修正方法 (approach) が無いことを報告する。必須かどうかは
			// status ごとに決まる (スキーマ表の approach の行)。修正に進む状態
			// (pending) と修正を終えた状態 (done / done-external) では必須、awaiting-human
			// では任意 (人間の立案待ちは approach を持たず、人間の回答の後に書く)、not-fixed
			// でも任意 (直さないと決めた問題)、investigated では逆に書いてあれば報告する。
			approachRequired := func() {
				if pl.Approach == "" {
					add("%s: approach がありません", pn)
				}
			}
			// noSHAYet はまだ修正していない状態 (investigated / pending / awaiting-human / not-fixed) の
			// 共通の検査で、done-external 専用のキーが無く、sha も無いことを確認する。
			noSHAYet := func() {
				externalOnly()
				if pl.SHA != "" {
					add("%s: status %s なのに sha %q があります。直したのなら status: done にする", pn, pl.Status, pl.SHA)
				}
			}
			// statusKnown は status が列挙の値か。列挙外なら default が列挙違反を報告するので、decision と
			// 状態を組み合わせる検査はしない。重ねると 1 つの誤字が 2 つの問題になるため。
			statusKnown := true
			switch pl.Status {
			case "investigated":
				// 調査フェーズの結果だけを持つ状態。修正方法と順序は立案フェーズが書いて
				// pending / awaiting-human に進める。ここに書いてあると、立案フェーズが書いたのか
				// 調査フェーズが立案フェーズの中身まで書いたのかを記録から読めなくなるので、書いてあれば報告する。
				noSHAYet()
				// 調査 (investigation) は他の状態では任意だが、この状態では必須。
				// 無いことは「未調査」を意味する (スキーマ表) ので、調査済みの状態と矛盾する。
				// 通してしまうと、立案フェーズが未調査の問題に立案し、同じ原因の別の現れが残る。
				// 中身 (scope) の検査は下の inv != nil の検査に委ねる。
				if pl.Investigation == nil {
					add("%s: 調査済み (investigated) には investigation (調べた範囲と結果) が必須。"+
						"無いものは未調査で、状態と矛盾する。調べたなら scope を書き、まだなら plans に載せない", pn)
				}
				if pl.Approach != "" {
					add("%s: 調査済み (investigated) では approach を書かない。修正方法を決めたのなら status: pending にする", pn)
				}
				if pl.Order != 0 {
					add("%s: 調査済み (investigated) では order を書かない。順序を決めたのなら status: pending にする", pn)
				}
			case "pending", "awaiting-human":
				noSHAYet()
				if pl.Status == "pending" {
					approachRequired()
				}
				if pl.Status == "awaiting-human" && pl.Options == "" {
					add("%s: status awaiting-human には options (選択肢とトレードオフ) が必須", pn)
				}
			case "done":
				externalOnly()
				approachRequired()
				if pl.SHA == "" {
					add("%s: status done には sha (短縮 SHA) が必須。リポジトリ外の成果物への反映で"+
						"コミットが立たないなら status: done-external にする", pn)
				}
			case "done-external":
				approachRequired()
				// コミットが無いのだから sha を書けるはずがない。書けているなら
				// リポジトリ内の修正なので done が正しい。
				if pl.SHA != "" {
					add("%s: status done-external なのに sha %q があります。コミットがあるなら status: done にする", pn, pl.SHA)
				}
				if pl.AppliedExternalURL == "" && pl.Notes == "" {
					add("%s: status done-external には applied_external_url (反映先の URL) か "+
						"notes (反映先と、反映を確認した方法) のどちらかが必須", pn)
				}
			case "not-fixed":
				// 今回は直さないと人間が決めた問題。コミットも外部への反映も無い。
				noSHAYet()
			default:
				add("%s: status は investigated / pending / awaiting-human / done / done-external / not-fixed のいずれか: %q", pn, pl.Status)
				statusKnown = false
			}
			for _, m := range recordDecisionProblems(pl, statusKnown) {
				add("%s: %s", pn, m)
			}
			// 調査は investigated 以外の状態では任意 (無ければ未調査) だが、書くなら範囲 (scope) が要る。
			// 範囲の無い調査は「どこまで調べたか」を残さず、未調査と区別できない。
			if inv := pl.Investigation; inv != nil {
				if strings.TrimSpace(inv.Scope) == "" {
					add("%s: investigation.scope がありません (調べた範囲。実行したコマンドと目で読んだ対象を書く)。範囲を書かない調査は未調査と区別できない", pn)
				}
				for _, kv := range []struct {
					key  string
					vals []string
				}{{"included", inv.Included}, {"excluded", inv.Excluded}} {
					for i, v := range kv.vals {
						if strings.TrimSpace(v) == "" {
							add("%s: investigation.%s[%d] が空です (箇所を書くか要素を消す)", pn, kv.key, i)
						}
					}
				}
			}
			// doc-dag の確認 (doc_dag) は任意だが、書くなら対象 (scope) と結果 (result) が要る。
			// 片方だけの記録は、何を確認して何が分かったかを残さない。
			if dd := pl.DocDag; dd != nil {
				if strings.TrimSpace(dd.Scope) == "" {
					add("%s: doc_dag.scope がありません (doc-dag に渡した対象の文書群)", pn)
				}
				if strings.TrimSpace(dd.Result) == "" {
					add("%s: doc_dag.result がありません (どちらが SSOT か決まっていない重複・参照の循環の有無と対処)", pn)
				}
			}
			// 検証 (verification) は任意だが、書くなら再確認した範囲 (near_edges) が要る。
			// 範囲の無い検証は、読んだつもりの記録と読んでいない記録を区別できない。
			if ver := pl.Verification; ver != nil {
				if len(ver.NearEdges) == 0 {
					add("%s: verification.near_edges がありません (観点 B で再確認した範囲。nearedges の出力から写す)", pn)
				}
				for i, v := range ver.NearEdges {
					if strings.TrimSpace(v) == "" {
						add("%s: verification.near_edges[%d] が空です (範囲を書くか要素を消す)", pn, i)
					}
				}
			}
			for _, d := range pl.DependsOn {
				if d == pl.ProblemID {
					add("%s: depends_on が自己参照しています", pn)
					continue
				}
				if !problemIDs[d] {
					add("%s: depends_on の %q は同じ回の plans にありません", pn, d)
				}
			}
		}
		// 被覆: 採択は自回の plans か plan_ref で覆われる。覆われない採択は、
		// 対処しないまま、誰にも知らされずに消える。
		//
		// 免除するのは「plans がまだ無い最後の回」だけで、これは fix 前の状態を指す。
		// 後続の回が追記された時点でその回はもう fix 前ではないので、免除を解く。
		// 全回で len(run.Plans) > 0 を条件にしていた頃は、plans を書かないまま
		// 次の回に進んだ過去の回の採択が、検査からも review-triage-fix (最後の回の
		// findings しか見ない) からも見えなくなり、誰にも知らされずに消えていた。
		isLastRun := ri == len(doc.Runs)-1
		if len(run.Plans) > 0 || !isLastRun {
			covered := map[int]bool{}
			for _, pl := range run.Plans {
				for _, id := range pl.FindingIDs {
					covered[id] = true
				}
			}
			for _, fd := range run.Findings {
				if fd.Verdict != "adopted" || covered[fd.ID] {
					continue
				}
				if fd.PlanRef != nil {
					continue // 参照自体の実在は上の finding ループで検査済み
				}
				add("%s: findings id %d: 採択が修正計画に載っていません (自回の plans にも plan_ref にも無い)", rn, fd.ID)
			}
		}
		for _, cycle := range recordDependsOnCycles(run.Plans) {
			add("%s: depends_on が循環しています (%s)。順序が定まらない。同じ原因の 1 問題に束ねるべきものを分けていないかを疑う",
				rn, strings.Join(cycle, " → "))
		}
	}
	return problems
}

// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
func recordDependsOnCycles(plans []recordPlan) [][]string {
	deps := make(map[string][]string, len(plans))
	for _, pl := range plans {

	var problems []string
	fileSet := make(map[string]bool, len(files))
	for _, f := range files {
		fileSet[f] = true
	}
	var stems []string
	var mds []string
	for _, f := range files {
		if !inReviewTriageDir(f) || path.Base(f) == "README.md" {
			continue
		}
		switch {
		case strings.HasSuffix(f, ".yaml"):
			stems = append(stems, strings.TrimSuffix(f, ".yaml"))
		case strings.HasSuffix(f, ".md"):
			mds = append(mds, f)
		}
	}
	sort.Strings(stems)
	stemSet := make(map[string]bool, len(stems))
	for _, s := range stems {
		stemSet[s] = true
	}

	for _, stem := range stems {
		yf := stem + ".yaml"
		data, err := readFile(yf)
		if err != nil {
			problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", yf, err))
			continue
		}
		ps, doc := recordProblemsInYAML(yf, data)
		problems = append(problems, ps...)

		// サマリの鮮度。スキーマに問題がある間は比較しない (直せば両方直る)。
		mdPath := stem + ".md"
		if !fileSet[mdPath] {
			problems = append(problems, fmt.Sprintf(
				"%s: サマリ %s がありません (`%s` で生成してコミットする)", yf, mdPath, summaryCommand))
			continue
		}
		if len(ps) > 0 || doc == nil {
			continue
		}
		want := renderReviewTriageSummaryDoc(yf, doc)
		got, err := readFile(mdPath)
		if err != nil {
			problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", mdPath, err))
			continue
		}
		if string(got) != want {
			problems = append(problems, fmt.Sprintf(
				"%s: サマリが SSOT (%s) と一致しません (`%s` で再生成する)", mdPath, yf, summaryCommand))
		}
	}

	sort.Strings(mds)
	for _, md := range mds {
		if !stemSet[strings.TrimSuffix(md, ".md")] {
			problems = append(problems, fmt.Sprintf(
				"%s: 対応する YAML (SSOT) がありません。記録の SSOT は <ブランチ名>.yaml で、サマリはその生成物", md))
		}
	}
	return problems
}

// recordLineCommentProblems は行内コメント (LineComment) を持つノードを検出する。
// YAML の素のスカラーは半角スペースに続く # 以降をコメントとして取り除くため、
// 引用符の無い値に # を書くと値が警告なく切り詰められる (実測で cause が「PR」だけに
// なった)。切り詰められた分はパーサが LineComment として保持するので、そこを見る。
// 生テキストの正規表現で字句規則を再現する方式では、キーの形・空白・ブロックスカラー・
// 値全体のコメントと境界のたびに検出漏れが生じたため (字句の形を列挙する検査は、列挙に無い形が現れるたびに検出漏れを繰り返す。既知の種類の欠陥である)。
// ブロックスカラーの本文の # は内容でありコメントにならないので、構造的に区別される。
// 行頭コメント (HeadComment) は値を壊さないため対象にしない。
func recordLineCommentProblems(f string, root *yaml.Node) []string {
	var problems []string
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n.LineComment != "" {
			problems = append(problems, fmt.Sprintf(
				"%s:%d: 行内コメント (%q) は使えません。YAML は ' #' 以降をコメントとして取り除き、値が警告なく切り詰められる。値に # を含めるときは引用符で囲む",
				f, n.Line, n.LineComment))
		}
		for _, c := range n.Content {
			walk(c)
		}
	}
	walk(root)
	return problems
}

// recordProblemsInYAML は 1 ファイル分のスキーマ検査を行い、問題と (読めた場合の) 文書を返す。
func recordProblemsInYAML(f string, data []byte) ([]string, *recordDoc) {
	var root yaml.Node
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&root); err != nil {
		// 空・コメントのみ・空白のみは EOF になる。生の文言では実際の状態が読めない。
		if errors.Is(err, io.EOF) {
			return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
		}
		return []string{fmt.Sprintf("%s: YAML を解析できません: %v", f, err)}, nil
	}
	// 記録は単一ドキュメント。--- 区切りの 2 つ目以降は読まれずに消えるため、存在自体を拒否する。
	var extra yaml.Node
	if err := dec.Decode(&extra); err == nil {
		return []string{fmt.Sprintf(
			"%s: --- 区切りの 2 つ目のドキュメントがあります。記録は単一ドキュメントで、2 つ目以降は読まれず消える", f)}, nil
	} else if !errors.Is(err, io.EOF) {
		return []string{fmt.Sprintf("%s: 2 つ目のドキュメントの解析に失敗しました: %v", f, err)}, nil
	}
	if len(root.Content) == 0 ||
		(root.Content[0].Kind == yaml.ScalarNode && root.Content[0].Tag == "!!null") {
		// null・~・--- だけのファイルは null スカラーのルートとして解析され、
		// EOF にも空 Content にもならない。実質的に空なので同じ文言に揃える。
		return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
	}
	problems := recordLineCommentProblems(f, &root)
	problems = append(problems, recordUnknownKeyProblems(f, root.Content[0])...)
	var doc recordDoc
	if err := root.Decode(&doc); err != nil {
		problems = append(problems, fmt.Sprintf("%s: スキーマに合いません: %v", f, err))
		return problems, nil
	}
	problems = append(problems, recordSemanticProblems(f, &doc)...)
	return problems, &doc
}

// recordNullSilentKeys は、値を省いて null にすると他のどの検査でも失敗しない
// 構造キー。キーの有無をポインタの nil で見る plan_ref / investigation は、
// 「キーを書いて値を省いた」(書きかけ・インデントのミス) が「キーが無い」と
// 同一になり、書き込み元は書いたつもりのまま記録上は無い扱いになる (実測:
// investigation: だけの記録が検査 0 件でサマリにも出なかった)。
// 旧様式の recurrence も同じで、null は「無い」と同一になり、書きかけの項目が消える。
// consequence / premise_check の null は必須サブキーの欠落として既に報告されるので
// ここに含めない。重ねると 1 つの書き忘れが複数の問題になるため。
var recordNullSilentKeys = map[string]bool{"plan_ref": true, "prior_defect": true, "fix_necessity_reason": true, "below_minimum_ref": true, "decision": true, "investigation": true, "verification": true, "doc_dag": true, "recurrence": true}

// recordUnknownKeyProblems は許可キー集合との突き合わせで未知のキーと、
// 値の無い構造キー (recordNullSilentKeys) を列挙する。
// 問題が見つかっても走査を続け、他の問題の報告を妨げない。
func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
	var problems []string
	var walkMap func(n *yaml.Node, kind string)
	walkSeq := func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.SequenceNode {
			return
		}
		for _, item := range n.Content {
			walkMap(item, kind)
		}
	}
	walkMap = func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.MappingNode {
			return
		}
		allowed := recordAllowedKeys[kind]
		for i := 0; i+1 < len(n.Content); i += 2 {
			k, v := n.Content[i], n.Content[i+1]
			if !allowed[k.Value] {
				problems = append(problems, fmt.Sprintf(
					"%s:%d: %sに未知のキー %q。旧いキー名の残存か、キーを書く位置のミス (上流固有の属性は attrs へ) を疑う",
					f, k.Line, kind, k.Value))
				continue
			}
			if recordNullSilentKeys[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
				problems = append(problems, fmt.Sprintf(
					"%s:%d: %s の %s に値がありません。書くなら中身を書き、書かないならキーごと消す (値の無いキーは「無い」と同じに扱われ、書いたつもりの記録が警告なく消える)",
					f, k.Line, kind, k.Value))
				continue
			}
			switch k.Value {
			case "runs":
				walkSeq(v, "実行")
			case "findings":
				walkSeq(v, "指摘")
			case "plans":
				walkSeq(v, "修正計画")
			case "consequence":
				walkMap(v, "帰結")
			case "premise_check":
				walkMap(v, "根拠の検証")
			case "plan_ref":
				walkMap(v, "束ね先")
			case "prior_defect":
				walkMap(v, "前からある欠陥")
			case "fix_necessity_reason":
				walkMap(v, "必要度の理由")
			case "below_minimum_ref":
				walkMap(v, "下限未満の参照")
			case "investigation":
				walkMap(v, "調査")
			case "verification":
				walkMap(v, "検証")
			case "doc_dag":
				walkMap(v, "doc-dag の確認")
			case "decision":
				walkMap(v, "立案の結果")
			case "recurrence":
				walkMap(v, "検知")
			case "evidence":
				walkSeq(v, "根拠")
			case "reframe":
				walkMap(v, "捉え直し")
			}
		}
	}
	walkMap(n, "トップレベル")
	return problems
}

var recordDateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)

// renderReviewTriageSummary は記録 YAML から人が読むサマリ (Markdown) を生成する。
// 件数はすべてここで計算し、人が書いた集計をどこからも読まない。
func renderReviewTriageSummary(yamlPath string, data []byte) (string, error) {
	var doc recordDoc
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return "", fmt.Errorf("%s: YAML を読めません: %w", yamlPath, err)
	}
	return renderReviewTriageSummaryDoc(yamlPath, &doc), nil
}

func renderReviewTriageSummaryDoc(yamlPath string, doc *recordDoc) string {
	base := path.Base(yamlPath)
	stem := strings.TrimSuffix(base, ".yaml")
	var b strings.Builder
	fmt.Fprintf(&b, "<!-- 生成物。手で編集しない。SSOT は %s。`%s` で再生成する。 -->\n\n", base, summaryCommand)
	fmt.Fprintf(&b, "# %s のトリアージ記録\n\n", stem)
	fmt.Fprintf(&b, "SSOT は [%s](%s)。読み方と収束の目安は [README](README.md)。\n\n", base, base)

	b.WriteString("## 推移\n\n")
	b.WriteString("| 回 | 日付 | スキル | model | scope | 下限 | 全件 | 採択 | 保留 | 却下 | 下限未満 | Must | Should | Could |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
	fixNecessityFirstRun := recordFixNecessityFirstRun(doc.Runs)
	for i, run := range doc.Runs {
		adopted, held, rejected, belowMinimum := 0, 0, 0, 0
		for _, fd := range run.Findings {
			switch fd.Verdict {
			case "adopted":
				adopted++
			case "held":
				held++
			case "rejected":
				rejected++
			case "below_minimum":
				belowMinimum++
			}
		}
		minimum := "—"
		if run.MinFixNecessity != "" {
			minimum = recordCell(run.MinFixNecessity)
		}
		// 自由文字列の欄 (skill・model など) は recordCell で無害化する。縦棒が
		// 入ると桁がずれ、偽の数字が集計値の手前に並ぶため (列挙で守られない欄は検査も
		// 捕まえない)。
		fmt.Fprintf(&b, "| %d | %s | `%s` | `%s` | %s | %s | %d | %d | %d | %d | %d | %s |\n",
			i+1, recordCell(run.Date), recordCell(run.Skill), recordCell(run.Model),
			recordCell(run.Scope), minimum, len(run.Findings), adopted, held, rejected, belowMinimum,
			strings.Join(renderFixNecessityCounts(doc, i, fixNecessityFirstRun), " | "))
	}
	renderBelowMinimumSection(&b, doc)

	for i, run := range doc.Runs {
		// 鮮度の検査は描画結果の全文一致なので、サマリに出す文言を変えると、ディレクトリに残る
		// 既存のサマリがすべて古いと報告される。0.24.0 で回の書き方を「N 回目」に変えたときは、
		// 再生成が要ることを README の「生成サマリの書式の変更」に書いた。束ね先・根拠の行・
		// 出所の文言も同じ。
		fmt.Fprintf(&b, "\n## %d 回目: %s `%s`", i+1, recordCell(run.Date), recordCell(run.Skill))
		if run.RunID != "" {
			fmt.Fprintf(&b, " (%s)", recordCell(run.RunID))
		}
		b.WriteString("\n\n")
		fmt.Fprintf(&b, "- HEAD `%s` / model `%s` / scope %s",
			recordCell(run.Head), recordCell(run.Model), recordCell(run.Scope))
		if run.Level != "" {
			b.WriteString(" / level " + recordCell(run.Level))
		}
		b.WriteString("\n\n")

		b.WriteString("| # | 指摘 | 分類 / 被害者 | 帰結 (条件 / 何が / 気づかされるか) | 検証 | ゲート | 判定 |\n")
		b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
		for _, fd := range run.Findings {
			b.WriteString(recordRow(renderFindingCells(fd)))
		}

		// 旧様式の検知の項目。既存の生成サマリを書き換えないよう、位置 (修正計画の前)
		// と文面を変えない。推移の表にも列を足さない。無い回には出さない (検知を
		// 廃止した後の回は常に無い)。
		if run.Recurrence != nil {
			b.WriteString("\n### 検知\n\n")
			renderRecurrence(&b, run.Recurrence)
		}

		if len(run.Plans) > 0 {
			b.WriteString("\n### 修正計画\n\n")
			// 最終列の見出しは「証拠」にする。最終列は、コミットの SHA だけでなくリポジトリ外の
			// 反映先の URL も取るため (renderPlanCells の証拠の欄)。見出しを SHA のままにすると、
			// done-external の行に出る URL を SHA として読ませることになる。
			b.WriteString("| 問題 | 原因 | 含む指摘 | 修正方法 | 順 | 状態 | 証拠 (SHA / URL) |\n")
			b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
			for _, pl := range run.Plans {
				b.WriteString(recordRow(renderPlanCells(pl)))
			}
			// 調査済み・未立案 (investigated) の注記。調査フェーズの結果だけがあり、修正方法と
			// 順序をまだ持たない問題が残っている回にだけ、表の下に件数と問題 id を出す。
			// 無い回には 1 バイトも出さず、推移の表にも列を足さない。鮮度の検査が描画結果の
			// 全文一致なので、無い記録の出力が変わるとディレクトリの既存サマリがすべて古いと
			// 報告されるため (旧様式の検知の小節と同じ形)。
			renderInvestigatedNote(&b, run.Plans)
			for _, pl := range run.Plans {
				if pl.Status == "awaiting-human" {
					fmt.Fprintf(&b, "\n- **%s は選択待ち (人間が選ぶ)**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Options))
				}
			}
			// リポジトリ外への反映は、コミットを辿っても内容を確認できない。
			// 反映を確認した方法 (notes) を表の外に出して、後から追えるようにする。
			for _, pl := range run.Plans {
				if pl.Status == "done-external" && pl.Notes != "" {
					fmt.Fprintf(&b, "\n- **%s はリポジトリ外へ反映済み**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Notes))
				}
			}
			// 直す前の調査の範囲と結果。次のレビューで同じ種類の指摘が来たとき、前回の
			// 調査漏れ (範囲の外だった) か新規かを判別する材料なので表の外に出す。
			// 無い問題は出さない。無いことが「未調査」を表すため。
			for _, pl := range run.Plans {
				if pl.Investigation != nil {
					fmt.Fprintf(&b, "\n- **%s の調査**: %s\n", recordCell(pl.ProblemID), renderInvestigation(pl.Investigation))
				}
			}
			// 立案の結果。無い問題の行は出さない。無い記録の出力が変わると、既存のサマリがすべて古いと報告されるため。
			for _, pl := range run.Plans {
				if pl.Decision != nil {
					fmt.Fprintf(&b, "\n- **%s の立案**: %s\n", recordCell(pl.ProblemID), renderDecision(pl.Decision))
				}
			}
		}

		if run.Notes != "" {
			b.WriteString("\n### 観察\n\n" + strings.TrimRight(run.Notes, "\n") + "\n")
		}
	}
	return b.String()
}

// recordRow はセルのスライスから表の 1 行を組み立てる。
func recordRow(cells []string) string {
	return "| " + strings.Join(cells, " | ") + " |\n"
	return cell
}

// renderPlanCells は修正計画 1 件の表のセルのスライスを返す。
func renderPlanCells(pl recordPlan) []string {
	var ids []string
	for _, id := range pl.FindingIDs {
		ids = append(ids, "#"+strconv.Itoa(id))
	}
	order := "—"
	if pl.Order > 0 {
		order = strconv.Itoa(pl.Order)
	}
	if len(pl.DependsOn) > 0 {
		order += " (" + recordCell(strings.Join(pl.DependsOn, ", ")) + " の後)"
	}
	// 証拠の欄。コミットがあれば SHA、リポジトリ外への反映なら反映先の URL を出す。
	// URL をコードスパンで包むのは、記録が引用を含む文書で、リンク記法にすると
	// リンク切れ検査に引っかかるため (record-schema.md の「表記の機械検査から外す」)。
	sha := "—"
	switch {
	case pl.SHA != "":
		sha = "`" + recordCell(pl.SHA) + "`"
	case pl.AppliedExternalURL != "":
		sha = "`" + recordCell(pl.AppliedExternalURL) + "`"
	}
	// 修正方法の欄。investigated (と人間の立案待ちの awaiting-human、直さない not-fixed) は approach を
	// 持たないので、空のセルではなく順序の欄と同じ「—」を出す。空のセルは書き忘れと
	// 区別できないため。approach を持つ状態の行は変わらない。
	approach := "—"
	if pl.Approach != "" {
		approach = recordCell(pl.Approach)
	}
	return []string{
		recordCell(pl.ProblemID),
		recordCell(pl.Cause),
		strings.Join(ids, " "),
		approach,
		order,
		recordStatusJa(pl.Status),
		sha,
	}
}

// renderInvestigatedNote は調査済み・未立案 (status investigated) の問題の件数と id を
// 修正計画の表の下に 1 行で出す。該当する問題が無ければ何も書かない。件数はここで
// 数え、人が書いた集計をどこからも読まない (推移の表と同じ)。
func renderInvestigatedNote(b *strings.Builder, plans []recordPlan) {
	var ids []string
	for _, pl := range plans {
		if pl.Status == "investigated" {
			ids = append(ids, recordCell(pl.ProblemID))
		}
	}
	if len(ids) == 0 {
		return
	}
	fmt.Fprintf(b, "\n- **調査済み・未立案 (investigated) が %d 件: %s。** 修正方法と順序をまだ持たない。`review-triage-fix` が立案フェーズから続ける\n",
		len(ids), strings.Join(ids, ", "))
}

// renderInvestigation は調査の範囲と結果を 1 行にする。included / excluded が
// 両方空なら「波及先なし」と明示する。範囲だけ出すと、調べて無かったのか
// 結果を書き忘れたのかが読めないため。
func renderInvestigation(inv *recordInvestigation) string {
	s := "範囲: " + recordCell(inv.Scope)
	if len(inv.Included) == 0 && len(inv.Excluded) == 0 {
		return s + " / 波及先なし"
	}
	join := func(items []string) string {
		cells := make([]string, 0, len(items))
		for _, it := range items {
			cells = append(cells, recordCell(it))
		}
		return strings.Join(cells, "; ")
	}
		return "スキルの見解 (skill)"
	}
	return recordCell(s)
}

// recordCell は表のセルに入れる文字列を 1 行に整える。
func recordCell(s string) string {
	return strings.NewReplacer("|", "\\|", "\n", " ").Replace(strings.TrimSpace(s))
}

func recordVerdictJa(v string) string {
	switch v {
	case "adopted":
		return "**採択**"
	case "held":
		return "**保留**"
	case "rejected":
		return "**却下**"
	case "below_minimum":
		return "**下限未満**"
	}
	return v
}

func recordStatusJa(s string) string {
	switch s {
	case "investigated":
		return "調査済み"
	case "pending":
		return "未着手"
	case "awaiting-human":
		return "**選択待ち**"
	case "done":
		return "済"
	case "done-external":
		return "済 (リポジトリ外)"
	case "not-fixed":
		return "直さない"
	}
	return s
}

// errRecordDirMissing は「明示指定したディレクトリが無い」ことを表す番兵。呼び出し元が
// errors.Is で判別し、他の検査を続けたうえで報告に積めるようにする。即座に返すと
// 判定フローの検査に到達せず、片方を直して再実行するまでもう一方の不在を知れないため。
// 権限・I/O のエラーは続行しても意味が無いので、これとは区別して返す。
var errRecordDirMissing = errors.New(
	"-record-dir に指定されたディレクトリが存在しません (記録の検査が行われないまま成功するため報告する)")

// listReviewTriageFiles は記録のディレクトリのファイル (yaml と md) をファイルシステムから
// 列挙する。doccheck の他の検査は git 追跡ファイルを対象にするが、記録は
// 「これから追跡される」ファイルなので、追跡前でも検査・生成の対象に入れる。
// git add 前の最初の記録が検査の対象に入らず、0 件マッチのまま検査が成功する種類の欠陥を防ぐため。
//
// ディレクトリが無いときの扱いは explicit で分かれる。ディレクトリを明示的に渡すこと
// (-record-dir) は「そこを検査せよ」という意思表示なので、不在はエラーにする。
// 未指定 (デフォルト値) のまま不在なのはスキル未導入の正常な状態で、nil を返す。
// 判定を分けないと、ディレクトリを移した時点で検査が無効になり、利用者はそれに気づけない
// (judgment_flow.go の explicit と同じ理由)。
func listReviewTriageFiles(dir string, explicit bool) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		// ディレクトリが無いのはスキル未導入の正常な状態 (明示指定のときを除く)。
		// それ以外 (権限・I/O) のエラーを「記録 0 件」に潰すと、検査が行われなくなり、利用者はそれに気づけない。
		// 判定は judgment_flow.go と同じ errors.Is に揃える (ラップされたエラーも
		// 正しく分類するため)。
		if errors.Is(err, fs.ErrNotExist) {
			if explicit {
				return nil, errRecordDirMissing
			}
			return nil, nil
		}
		return nil, err
	}
	var files []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		// README.* は記録ではない。README.md は手書きの規範文書で、README.yaml を
		// 記録と見なすと生成器が README.md を上書きしてしまうため (検査での除外と対称にする)。
		if strings.TrimSuffix(strings.TrimSuffix(name, ".md"), ".yaml") == "README" {
			continue
		}
		if strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".md") {
			files = append(files, path.Join(dir, name))
		}
	}
	sort.Strings(files)
	return files, nil
}

// writeReviewTriageSummaries は記録 YAML すべてについてサマリを再生成する
// (-write-summary の経路)。explicit は listReviewTriageFiles と同じ意味を持つ。
// 明示指定したディレクトリが無いなら、0 件生成して、エラーを出さずに成功させない。
func writeReviewTriageSummaries(dir string, explicit bool) error {
	files, err := listReviewTriageFiles(dir, explicit)
	if err != nil {
		return err
	}
	for _, f := range files {
		if !strings.HasSuffix(f, ".yaml") {
			continue
		}
		data, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		summary, err := renderReviewTriageSummary(f, data)
		if err != nil {
			return err
		}
		mdPath := strings.TrimSuffix(f, ".yaml") + ".md"
		if err := os.WriteFile(mdPath, []byte(summary), 0o644); err != nil {
			return err
		}
		fmt.Printf("生成: %s (SSOT: %s)\n", mdPath, f)
	}
	return nil
}

package main

import (
	"strings"
	"testing"
)

// decisionPlanOld は、validRecordYAML の問題 P1 の状態と立案の結果。
const decisionPlanOld = "        status: pending\n" +
	"        decision:\n" +
	"          target: docs/foo.md の 10 行目\n" +
	"          baseline: 実際の件数\n" +
	"          choice: baseline\n" +
	"          choice_reason: 実際の件数が実測の値である\n"

// decisionBaselineYAML は、基準の内容を正として消す立案の結果。
const decisionBaselineYAML = "        decision:\n" +
	"          target: docs/foo.md の 10 行目\n" +
	"          baseline: 記録の数\n" +
	"          choice: baseline\n" +
	"          choice_reason: 記録の数が実測の値である\n" +
	"          doc_change: remove\n"

// decisionRecordYAML は、validRecordYAML の問題 P1 に立案の結果を書いた記録。
func decisionRecordYAML(t *testing.T, decision, status string) string {
	t.Helper()
	if !strings.Contains(validRecordYAML, decisionPlanOld) {
		t.Fatalf("フィクスチャの置換が適用されていない: %q", decisionPlanOld)
	}
	return strings.Replace(validRecordYAML, decisionPlanOld, decision+"        status: "+status+"\n", 1)
}

func decisionProblems(src string) []string {
	read := func(_ string) ([]byte, error) { return []byte(src), nil }
	var got []string
	for _, p := range reviewTriageRecordProblems([]string{reviewTriageDir + "feat-x.yaml"}, read) {
		// サマリを渡していないので、サマリが無いという問題は除く。
		if !strings.Contains(p, "サマリ") {
			got = append(got, p)
		}
	}
	return got
}

func TestReviewTriageRecordDecisionPasses(t *testing.T) {
	files, read := recordFiles(t, decisionRecordYAML(t, decisionBaselineYAML, "pending"))
	if problems := reviewTriageRecordProblems(files, read); len(problems) != 0 {
		t.Fatalf("立案の結果を書いた記録で問題が出た: %v", problems)
	}
}

// 今回は直さないと人間が決めた問題は、approach も sha も無くて通り、採択を覆う。
func TestReviewTriageRecordNotFixedPasses(t *testing.T) {
	src := strings.Replace(validRecordYAML,
		"        approach: 数え直して単位を書く\n        order: 1\n        sha: \"\"\n"+decisionPlanOld,
		"        decision:\n          target: docs/foo.md の 10 行目\n          baseline: 記録の数\n          choice: undecided\n          choice_reason: 別の Issue で直す\n        status: not-fixed\n", 1)
	if src == validRecordYAML {
		t.Fatal("フィクスチャの置換が適用されていない")
	}
	src += "  - date: \"2026-08-31\"\n    skill: code-review\n    model: sonnet-5\n    scope: incremental\n    head: abc1235\n    findings: []\n"
	files, read := recordFiles(t, src)
	if problems := reviewTriageRecordProblems(files, read); len(problems) != 0 {
		t.Fatalf("not-fixed の記録で問題が出た: %v", problems)
	}
	summary, err := renderReviewTriageSummary(reviewTriageDir+"feat-x.yaml", []byte(src))
	if err != nil {
		t.Fatalf("サマリの生成に失敗: %v", err)
	}
	for _, want := range []string{
		"| P1 | 数えずに書いた | #1 | — | — | 直さない | — |",
		"- **P1 の立案**: 箇所: docs/foo.md の 10 行目 / 基準: 記録の数 / 選択: 決めない / 理由: 別の Issue で直す\n",
	} {
		if !strings.Contains(summary, want) {
			t.Fatalf("生成サマリに %q が無い:\n%s", want, summary)
		}
	}
}

// status の誤字は、列挙違反の 1 件だけを報告する。decision の検査 (undecided と状態の組み合わせ) を
// 重ねると、1 つの誤字が 2 つの問題として報告される。
func TestReviewTriageRecordDecisionUnknownStatusReportedOnce(t *testing.T) {
	undecided := strings.Replace(decisionBaselineYAML, "choice: baseline", "choice: undecided", 1)
	undecided = strings.Replace(undecided, "          doc_change: remove\n", "", 1)
	problems := decisionProblems(decisionRecordYAML(t, undecided, "not_fixed"))
	enum := 0
	for _, p := range problems {
		if strings.Contains(p, "status は investigated / pending") {
			enum++
		}
		if strings.Contains(p, "decision.") {
			t.Fatalf("status の誤字に decision の問題が重なった: %v", problems)
		}
	}
	if enum != 1 {
		t.Fatalf("列挙違反が 1 件ではない (%d 件): %v", enum, problems)
	}
}

// status の誤字があっても、status に関係しない decision の検査 (choice の列挙など) は行う。
// 行わないのは、status と組み合わせる検査だけである。
func TestReviewTriageRecordDecisionChecksWithUnknownStatus(t *testing.T) {
	typo := strings.Replace(decisionBaselineYAML, "choice: baseline", "choice: basline", 1)
	problems := decisionProblems(decisionRecordYAML(t, typo, "pendng"))
	var enum, choice bool
	for _, p := range problems {
		if strings.Contains(p, "status は investigated / pending") {
			enum = true
		}
